//! Agente Code brand bits shared by the TUI and its HTML surfaces.
//!
//! The artwork lives in `assets/brand/` (generated by `examples/gen_brand.rs`
//! from the traced app mark); this module only embeds what the app needs. The
//! welcome card paints the same glyph in half blocks (`widgets::welcome`).

/// Product name, used for the terminal title and page titles.
pub const PRODUCT_NAME: &str = "Agente Code";

/// The 16–32 px optical variant of the tile icon, as SVG: a favicon is drawn
/// at exactly those sizes.
const ICON_SVG: &str = include_str!("../../../assets/brand/agente-code-icon-small.svg");

/// `<link rel="icon">` carrying the tile icon as an inline SVG data URL, so
/// the exported gallery and the inspector page need no asset server.
pub fn favicon_link() -> String {
    let compact: String = ICON_SVG
        .lines()
        .map(str::trim)
        .collect::<Vec<_>>()
        .join(" ")
        .replace('"', "'");
    let mut encoded = String::with_capacity(compact.len() + 64);
    for c in compact.chars() {
        match c {
            '#' => encoded.push_str("%23"),
            '<' => encoded.push_str("%3C"),
            '>' => encoded.push_str("%3E"),
            '%' => encoded.push_str("%25"),
            c => encoded.push(c),
        }
    }
    format!(r#"<link rel="icon" type="image/svg+xml" href="data:image/svg+xml,{encoded}">"#)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn favicon_is_a_self_contained_data_url() {
        let link = favicon_link();
        assert!(link.starts_with(
            r#"<link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg"#
        ));
        let url = link
            .split_once("href=\"")
            .and_then(|(_, rest)| rest.strip_suffix("\">"))
            .expect("href value");
        assert!(!url.contains('"'), "attribute stays quoted");
        assert!(!link.contains('#'), "fragment chars are escaped");
    }

    #[test]
    fn favicon_is_the_current_mark() {
        // The traced mark fills even-odd on a black tile; the old ember
        // split-A carried its orange tile.
        assert!(ICON_SVG.contains("evenodd"));
        assert!(!ICON_SVG.to_lowercase().contains("e76d1f"));
    }
}
